  const px = this.px;
  const addx = (SHIELD_COLOR_RUN << 16) / MAX_SHIELD;
  let curs = 0;
  for (let loop = 0; loop < MAX_SHIELD; loop++) {
    const row = (199 - loop) * 320;
    const c = loop < level ? 74 - Math.trunc(curs / 65536) : 0;
    for (let i = 0; i < 4; i++) px[row + xpos + i] = c;
    curs += addx;
  }
}

// RAP_PrintNum
printNum(x, y, str) {
  this.putSprite(this.numbers[10], x, y);
  let xx = x + 9;
  for (const ch of str) {
    const num = ch.charCodeAt(0) - 48;
    if (num >= 0 && num <= 9) this.putSprite(this.numbers[num], xx, y);
    xx += 8;
  }
}

// RAP_DisplayStats + OBJS_DisplayStats
displayStats() {
  const superNum = this.superShield ? this.superShield.num : 0;
  const shield = this.energy ? this.energy.num : 0;

  if (this.g_oldsuper !== superNum) {
    this.displayShieldLevel(MAP_LEFT - 8, superNum);
    this.g_oldsuper = superNum;
  }
  if (this.g_oldshield !== shield) {
    this.displayShieldLevel(MAP_RIGHT + 4, shield);
  }

  // == player death sequence ==
  if (shield <= 0 && this.state === 'playing') {
    this.startAnim(A_MED_AIR_EXPLO, this.playerx + this.random(32), this.playery + this.random(32));
    this.startAnim(A_SMALL_AIR_EXPLO, this.playerx + this.random(32), this.playery + this.random(32));
    if (this.startendwave > END_EXPLODE) {
      if (this.random(2) === 0) this.sfx(FX.AIREXPLO, 30);
      else this.sfx(FX.AIREXPLO, 225);
    }
    if (this.startendwave === EMPTY) this.startendwave = END_DURATION;
    if (this.startendwave === END_EXPLODE) {
      this.draw_player = false;
      this.sfx(FX.AIREXPLO, 127);
      this.sfx(FX.AIREXPLO2, 127);
      this.startAnim(A_LARGE_AIR_EXPLO, this.player_cx, this.player_cy);
      for (let loop = 0; loop < (PLAYERWIDTH * PLAYERHEIGHT) / 2; loop++) {
        const x = this.playerx - (PLAYERWIDTH / 2) + this.random(PLAYERWIDTH * 2);
        const y = this.playery - (PLAYERHEIGHT / 2) + this.random(PLAYERHEIGHT * 2);
        if (loop & 1) this.startAnim(A_LARGE_AIR_EXPLO, x, y);
        else this.startAAnim(A_MED_AIR_EXPLO2, x, y);
      }
      this.sfx(FX.AIREXPLO2, 127);
    }
  }

  // == end-of-wave flyoff ==
  if (this.startendwave !== EMPTY && shield > 0) {
    if (this.startendwave === END_FLYOFF) {
      this.sfx(FX.FLYBY, 127);
      this._flyoff_done = true;
    }
    if (this.startendwave < END_FLYOFF) {
      let x = 0;
      if (this.playerx < (160 - 8)) x = 8;
      else if (this.playerx > (160 + 8)) x = -8;
      this.fmovePlayer(x, -4);
    }
  }

  // == low shield warning ==
  if (shield <= SHIELD_LOW && this.state === 'playing') {
    if ((this.gl_cnt % 8) === 0) {
      this._blinkflag = !this._blinkflag;
      if (this._blinkflag && this._damage) this._damage--;
    }
    if (shield < this.g_oldshield && superNum < 1) {
      if (this.loseObj()) {
        this.sfx(FX.CRASH, 127);
        this._damage = 2;
      }
    }

