// temp M4 contract browser check (deleted after run)
import { spawn } from 'node:child_process';
import path from 'node:path';
import os from 'node:os';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const PORT = 8765;
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

function findChrome() {
  const env = process.platform === 'win32'
    ? (process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local'))
    : (process.env.HOME || os.homedir());
  const base = path.join(env, 'ms-playwright');
  if (!fs.existsSync(base)) return null;
  const dirs = fs.readdirSync(base)
    .filter((d) => d.startsWith('chromium-') && !d.includes('headless_shell'))
    .sort().reverse();
  for (const d of dirs) {
    for (const sub of ['chrome-win64', 'chrome-linux', 'chrome-mac']) {
      const exe = path.join(base, d, sub, process.platform === 'win32' ? 'chrome.exe' : 'chrome');
      if (fs.existsSync(exe)) return exe;
    }
  }
  return null;
}
const chrome = findChrome();
if (!chrome) { console.error('no bundled chromium found under ms-playwright'); process.exit(2); }

const dbgPort = 9333 + Math.floor(Math.random() * 100);
const profile = fs.mkdtempSync(path.join(os.tmpdir(), 'raptor-cdp-'));
const chromeProc = spawn(chrome, [
  `--remote-debugging-port=${dbgPort}`,
  `--user-data-dir=${profile}`,
  '--disable-gpu',
  '--no-first-run',
  '--no-default-browser-check',
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });

let failures = 0;
function check(cond, msg) {
  if (!cond) failures++;
  console.log((cond ? 'ok  : ' : 'FAIL: ') + msg);
}
async function getJson(url, method = 'GET') {
  const r = await fetch(url, { method });
  return r.json();
}
async function waitForDebugger() {
  for (let i = 0; i < 50; i++) {
    try {
      const l = await getJson(`http://127.0.0.1:${dbgPort}/json/list`);
      if (Array.isArray(l) && l.length) return;
    } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error('chrome debugger not reachable');
}
class CDP {
  constructor(ws) { this.ws = ws; this.id = 0; this.pending = new Map(); }
  static async connect(url) {
    const ws = new WebSocket(url);
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
    const c = new CDP(ws);
    ws.onmessage = (m) => {
      const msg = JSON.parse(m.data);
      if (msg.id && c.pending.has(msg.id)) {
        const { res, rej } = c.pending.get(msg.id);
        c.pending.delete(msg.id);
        msg.error ? rej(new Error(msg.error.message)) : res(msg.result);
      }
    };
    return c;
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((res, rej) => this.pending.set(id, { res, rej }));
  }
  close() { try { this.ws.close(); } catch { /* ignore */ } }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Audio probe: wraps AudioContext + BufferSourceNode.start BEFORE page scripts run,
// to prove a real AudioBuffer (non-trivial sample data) is scheduled on fire.
const PROBE = `(() => {
  window.__ap = { ctx: null, state: 'none', starts: [] };
  const OrigAC = window.AudioContext || window.webkitAudioContext;
  if (!OrigAC) return;
  const Wrapped = function (...a) {
    const c = new OrigAC(...a);
    window.__ap.ctx = c;
    const st = () => { window.__ap.state = c.state; };
    st();
    c.addEventListener('statechange', st);
    return c;
  };
  Wrapped.prototype = OrigAC.prototype;
  window.AudioContext = Wrapped;
  window.webkitAudioContext = Wrapped;
  const origStart = AudioBufferSourceNode.prototype.start;
  AudioBufferSourceNode.prototype.start = function (...a) {
    try {
      const b = this.buffer;
      if (b) {
        const ch = b.getChannelData(0);
        let nz = 0, mx = 0;
        for (let i = 0; i < ch.length; i += 4) {
          const v = ch[i];
          if (v) nz++;
          const av = v < 0 ? -v : v;
          if (av > mx) mx = av;
        }
        window.__ap.starts.push({ len: b.length, rate: b.sampleRate, nz, mx });
      }
    } catch (e) { /* ignore */ }
    return origStart.apply(this, a);
  };
})();`;

try {
  await waitForDebugger();
  const target = await getJson(`http://127.0.0.1:${dbgPort}/json/new?http://127.0.0.1:${PORT}/`, 'PUT');
  const cdp = await CDP.connect(target.webSocketDebuggerUrl);
  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Page.addScriptToEvaluateOnNewDocument', { source: PROBE });
  const evalJs = async (expr) => {
    const r = await cdp.send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (r.exceptionDetails) throw new Error('page exception: ' + JSON.stringify(r.exceptionDetails).slice(0, 500));
    return r.result.value;
  };

  let ready = false;
  for (let i = 0; i < 120; i++) {
    ready = await evalJs(`window.__raptor && window.__raptor.ready === true`).catch(() => false);
    if (ready) break;
    await sleep(250);
  }
  check(ready, 'booted, ready true');
  if (!ready) throw new Error('boot failed');

  const press = (type, key) => cdp.send('Input.dispatchKeyEvent', {
    type, key, code: key === ' ' ? 'Space' : key,
    windowsVirtualKeyCode: key === ' ' ? 32 : { ArrowLeft: 37, ArrowRight: 39, ArrowUp: 38, ArrowDown: 40 }[key],
  });

  // == audio: gesture unlocks context ==
  await press('keyDown', 'ArrowLeft');
  await sleep(300);
  await press('keyUp', 'ArrowLeft');
  let st = await evalJs(`window.__ap.state`);
  for (let i = 0; i < 20 && st !== 'running'; i++) { await sleep(100); st = await evalJs(`window.__ap.state`); }
  check(st === 'running', `AudioContext reaches running after key gesture (${st})`);
  const rs0 = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
  check(rs0.audio.contextState === 'running', `__raptor.audio.contextState running (${rs0.audio.contextState})`);

  // == audio: fire triggers a real SFX buffer ==
  const sfx0 = await evalJs(`window.__raptor.audio.sfxCount`);
  const starts0 = await evalJs(`window.__ap.starts.length`);
  await press('keyDown', ' ');
  await sleep(1200);
  await press('keyUp', ' ');
  await sleep(300);
  const sfx1 = await evalJs(`window.__raptor.audio.sfxCount`);
  const starts = await evalJs(`window.__ap.starts`);
  check(sfx1 > sfx0, `fire increments audio.sfxCount (${sfx0} -> ${sfx1})`);
  const newOnes = starts.slice(starts0);
  check(newOnes.length > 0, `fire scheduled ${newOnes.length} BufferSource start(s) on the real AudioContext`);
  if (newOnes.length) {
    const b = newOnes[0];
    check(b.len > 500 && b.rate >= 8000 && b.rate <= 48000 && b.nz > 50 && b.mx > 0.02,
      `SFX buffer is real game audio data (len ${b.len}, rate ${b.rate}, nonzero ${b.nz}, max ${b.mx.toFixed(3)})`);
  }

  // == HUD pixels at boot: score digits, shield bar, weapon icon ==
  const region = (x0, y0, x1, y1) => evalJs(`(() => {
    const d = document.getElementById('raptor-canvas').getContext('2d').getImageData(0,0,320,200).data;
    let n = 0;
    for (let y = ${y0}; y < ${y1}; y++) for (let x = ${x0}; x < ${x1}; x++) {
      const o = (y * 320 + x) * 4;
      if (d[o] | d[o+1] | d[o+2]) n++;
    }
    return n;
  })()`);
  const scorePx = await region(119, 2, 200, 22);
  const barPx0 = await region(308, 100, 312, 200);
  const iconPx = await region(286, 2, 306, 22);
  check(scorePx > 40, `HUD score digits painted (x119 y2: ${scorePx} non-black px)`);
  check(barPx0 > 300, `HUD shield bar painted full (x308 y100-199: ${barPx0} non-black px, expect ~400)`);
  check(iconPx > 10, `HUD weapon icon painted (x286 y2: ${iconPx} px)`);

  // == HUD live: score rises on kills, digits repaint ==
  const score0 = rs0.hud.score;
  const shield0 = rs0.hud.shields;
  let scoreUp = false, t0 = Date.now();
  for (let i = 0; i < 60 && !scoreUp; i++) {
    if (i === 0) await press('keyDown', ' ');
    if (i % 8 === 0) {
      const cur = i % 16 === 0 ? 'ArrowLeft' : 'ArrowRight';
      await press('keyUp', i % 16 === 0 ? 'ArrowRight' : 'ArrowLeft');
      await press('keyDown', cur);
    }
    await sleep(500);
    const r = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
    if (r.hud.score > score0) scoreUp = true;
  }
  await press('keyUp', ' ');
  await press('keyUp', 'ArrowLeft'); await press('keyUp', 'ArrowRight');
  const r1 = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
  check(scoreUp, `__raptor.hud.score is live: kill raises score (${score0} -> ${r1.hud.score} in ${((Date.now() - t0) / 1000) | 0}s)`);
  const scorePx1 = await region(119, 2, 200, 22);
  check(scorePx1 !== scorePx, `score digits repainted (px ${scorePx} -> ${scorePx1})`);

  // == HUD live: shields fall when hit, bar drains ==
  const shieldBefore = r1.hud.shields;
  const barBefore = await region(308, 100, 312, 200);
  await press('keyDown', 'ArrowUp');
  let shieldsDown = false, alive = true;
  for (let i = 0; i < 48 && !shieldsDown; i++) {
    await sleep(500);
    const r = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
    if (r.hud.shields < shieldBefore) shieldsDown = true;
    alive = r.player.alive;
  }
  await press('keyUp', 'ArrowUp');
  const r2 = await evalJs(`JSON.parse(JSON.stringify(window.__raptor))`);
  const barAfter = await region(308, 100, 312, 200);
  check(shieldsDown, `__raptor.hud.shields is live: damage drains shields (${shieldBefore} -> ${r2.hud.shields}, player alive=${r2.player.alive})`);
  check(barAfter < barBefore, `shield bar drains on the canvas (px ${barBefore} -> ${barAfter})`);
  check(r2.audio.sfxCount > sfx1, `more SFX counted during play (hit/crash): ${sfx1} -> ${r2.audio.sfxCount}`);

  cdp.close();
} finally {
  chromeProc.kill();
  try { fs.rmSync(profile, { recursive: true, force: true }); } catch { /* ignore */ }
}
console.log(failures ? 'M4 BROWSER CHECK FAILED' : 'M4 BROWSER CHECK OK');
process.exit(failures ? 1 : 0);

