    for (const sub of ['chrome-win64', 'chrome-linux', 'chrome-mac']) {
      const exe = path.join(base, d, sub, process.platform === 'win32' ? 'chrome.exe' : 'chrome');
      if (fs.existsSync(exe)) return exe;
    }
