export class Sound {
  constructor(glb0) {
    this.glb0 = glb0;
    this.ctx = null;
    this.sfxCount = 0;
    this.buffers = new Map(); // fx -> AudioBuffer
    this.enabled = true;
  }

  // Must be called from a user gesture (keyboard/mouse) to unlock audio.
  ensure() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ctx = new AC();
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume().catch(() => {});
    }
    return this.ctx;
  }

  get state() {
    return this.ctx ? this.ctx.state : 'suspended';
  }

  // Decode the DSP patch for an FX into an AudioBuffer (cached).
  bufferFor(fx) {
    if (this.buffers.has(fx)) return this.buffers.get(fx);
    const info = FX_TABLE[fx];
    if (!info) return null;
    const label = this.glb0.find(info.label);
    if (!label) return null;
    const dsp = this.glb0.items[label.id + 4];
    if (!dsp || dsp.size < 16) return null;
    const d = this.glb0.data(dsp);
    const dv = new DataView(d.buffer, d.byteOffset, d.byteLength);
    const rate = dv.getUint16(2, true);
    const len = dv.getUint32(4, true);
    if (rate < 1000 || rate > 48000 || 8 + len > d.byteLength) return null;
    const n = len;
    const abuf = this.ctx.createBuffer(1, n, rate);
    const ch = abuf.getChannelData(0);
    for (let i = 0; i < n; i++) {
      ch[i] = (d[8 + i] - 128) / 128; // s8 -> [-1,1)
    }
    this.buffers.set(fx, abuf);
    return abuf;
  }

  // SND_Patch(fx, volume) -- volume 0..127 scales the FX's base volume.
  play(fx, volume = 127) {
    this.sfxCount++;
    if (!this.enabled) return;
    if (!this.ctx || this.ctx.state !== 'running') return;
    const info = FX_TABLE[fx];
    if (!info) return;
    const buf = this.bufferFor(fx);
    if (!buf) return;
    const src = this.ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = info.pitch / 128;
    const gain = this.ctx.createGain();
    gain.gain.value = (info.vol * volume) / (127 * 127);
    src.connect(gain).connect(this.ctx.destination);
    src.start();
  }
}

