  if (newOnes.length) {
    const b = newOnes[0];
    check(b.len > 500 && b.rate >= 8000 && b.rate <= 48000 && b.nz > 50 && b.mx > 0.02,
      `SFX buffer is real game audio data (len ${b.len}, rate ${b.rate}, nonzero ${b.nz}, max ${b.mx.toFixed(3)})`);
  }

