    if (i === 0) await press('keyDown', ' ');
    if (i % 8 === 0) {
      const cur = i % 16 === 0 ? 'ArrowLeft' : 'ArrowRight';
      await press('keyUp', i % 16 === 0 ? 'ArrowRight' : 'ArrowLeft');
      await press('keyDown', cur);
    }
